#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const sourcePath = path.resolve("docs/assistant-workflow.md");
const targets = ["AGENTS.md", "CLAUDE.md"];

function stripLeadingHeading(source) {
	return source.replace(/^# .+\n+/, "");
}

export function buildAssistantDoc(targetName) {
	const source = fs.readFileSync(sourcePath, "utf8").trim();
	const body = stripLeadingHeading(source).trim();

	return [
		`# ${targetName}`,
		"",
		"Generated from `docs/assistant-workflow.md`. Do not edit this file directly.",
		"Run `pnpm run generate:assistant-docs` after updating the canonical assistant workflow document.",
		"",
		body,
		"",
	].join("\n");
}

export function syncAssistantDocs({ check = false } = {}) {
	for (const target of targets) {
		const targetPath = path.resolve(target);
		const expected = buildAssistantDoc(target);
		const exists = fs.existsSync(targetPath);
		const stats = exists ? fs.lstatSync(targetPath) : null;
		const existing = exists && stats?.isFile() ? fs.readFileSync(targetPath, "utf8") : null;

		if (check) {
			if (!exists || !stats?.isFile() || existing !== expected) {
				throw new Error(`${target} is out of date. Run \`pnpm run generate:assistant-docs\`.`);
			}

			continue;
		}

		if (stats?.isSymbolicLink()) {
			fs.unlinkSync(targetPath);
		}

		fs.writeFileSync(targetPath, expected);
	}
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
	try {
		syncAssistantDocs({ check: process.argv.includes("--check") });
	} catch (error) {
		console.error(error instanceof Error ? error.message : error);
		process.exit(1);
	}
}
